from itertools import permutations

# Exhaustive check over all 4! room assignments.
NATS = ["South Korea", "France", "Britain", "Germany"]

# Languages each person speaks, taken from their statements:
# Korean: no foreign languages; French: speaks German; British: speaks Korean;
# German: speaks all four languages.
SPEAKS = {
    "South Korea": {"South Korea"},
    "France": {"France", "Germany"},
    "Britain": {"Britain", "South Korea"},
    "Germany": {"South Korea", "France", "Britain", "Germany"},
}

def comm(a, b):
    # Two people can communicate if they share at least one language.
    return bool(SPEAKS[a] & SPEAKS[b])

def neighbors(room):
    return [r for r in (room - 1, room + 1) if 1 <= r <= 4]

solutions = []
for perm in permutations(NATS):  # perm[i] lives in room i+1
    pos = {nat: i + 1 for i, nat in enumerate(perm)}

    def nb_comm_count(nat):
        return sum(1 for r in neighbors(pos[nat]) if comm(nat, perm[r - 1]))

    # Korean: room number larger than German's, cannot communicate with any neighbor.
    k_ok = pos["South Korea"] > pos["Germany"] and nb_comm_count("South Korea") == 0
    # French: speaks German (verified by SPEAKS), cannot communicate with any neighbor.
    f_ok = "Germany" in SPEAKS["France"] and nb_comm_count("France") == 0
    # British: speaks Korean, can communicate with exactly one neighbor.
    b_ok = "South Korea" in SPEAKS["Britain"] and nb_comm_count("Britain") == 1
    # German: speaks all four languages.
    g_ok = SPEAKS["Germany"] == set(NATS)

    if k_ok and f_ok and b_ok and g_ok:
        solutions.append(perm)

print("Consistent room orderings (room 1 -> room 4):")
for s in solutions:
    print("  ", s)
print("Number of solutions:", len(solutions))

options = {
    "A": ("Britain", "Germany", "South Korea", "France"),
    "B": ("France", "Britain", "Germany", "South Korea"),
    "C": ("Germany", "Britain", "France", "South Korea"),
    "D": ("Germany", "Britain", "South Korea", "France"),
}

if len(solutions) != 1:
    print("UNSUPPORTED: puzzle does not yield a unique ordering under this model.")
else:
    unique = solutions[0]
    for label, tup in options.items():
        status = "CHECK PASS" if tup == unique else "CHECK FAIL"
        print(f"Option {label}: {tup} -> {status}")
    print("Submitted answer D:", "CHECK FAIL" if options["D"] != unique else "CHECK PASS")
